<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}

require dirname(__DIR__).'/app/bootstrap.php';
$pdo=db();$catalogue=json_decode(file_get_contents(ROOT.'/app/products.json'),true,512,JSON_THROW_ON_ERROR);
$catalogue[]=['number'=>20,'name'=>'Catalogues','family'=>'Commercial Print + Branding','short'=>'Catalogue printing for product ranges, services and collections, scoped around your format and print specification.','description'=>'Prepare a catalogue for a product range, service collection or organization. Share the finished size, page count, binding preference, paper and GSM, print sides, color specification and quantity. HDC reviews the artwork and finishing details before confirming the production brief.','uses'=>'Product catalogues · service directories · collection guides','configure'=>'Size · page count · binding · paper/GSM · print sides · color count · quantity · artwork','template'=>'A — Standard Product Configurator','mode'=>'QUOTE','published'=>false,'status'=>'draft'];
$insert=$pdo->prepare('INSERT INTO products(slug,name,family,short_description,description,typical_uses,configuration_fields,template,commercial_mode,status,public_visibility,sort_order,source_metadata) VALUES(?,?,?,?,?,?,?,?,?,\'draft\',0,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),family=VALUES(family),short_description=VALUES(short_description),description=VALUES(description),typical_uses=VALUES(typical_uses),configuration_fields=VALUES(configuration_fields),template=VALUES(template),commercial_mode=VALUES(commercial_mode),sort_order=VALUES(sort_order)');
foreach($catalogue as $p){$template=str_starts_with((string)($p['template']??''),'B')?'B':'A';$mode=str_contains((string)($p['mode']??''),'TECHNICAL_REVIEW')?'TECHNICAL_REVIEW':'QUOTE';$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',iconv('UTF-8','ASCII//TRANSLIT',$p['name'])),'-'));$insert->execute([$slug,$p['name'],$p['family'],$p['short'],$p['description'],$p['uses']??'',$p['configure']??'',$template,$mode,$p['number'],json_encode(['source'=>'ORVIA product descriptions draft','status'=>'production-review-required'],JSON_UNESCAPED_UNICODE)]);}
$pdo->exec("INSERT INTO owner_price_rules(product_slug,rule_key,rule_json,source) VALUES ('custom-sticker-sheets','base_price',JSON_OBJECT('format','A3','currency','PKR','amount',2500,'unit','sheet','quantity_total_calculation',false),'Owner-confirmed in project brief'),('labels-stickers','base_price',JSON_OBJECT('format','A3','currency','PKR','amount',2500,'unit','sheet','quantity_total_calculation',false),'Owner-confirmed in project brief'),('catalogues','minimum_quantity',JSON_OBJECT('minimum',500,'unit','pieces'),'Owner-confirmed in project brief'),('posters','minimum_quantity',JSON_OBJECT('minimum',500,'unit','pieces'),'Owner-confirmed in project brief'),('catalogues','print_colors',JSON_OBJECT('allowed',JSON_ARRAY(1,2,4),'used_for_exact_price_matrix',true),'Owner-confirmed in project brief'),('posters','print_colors',JSON_OBJECT('allowed',JSON_ARRAY(1,2,4),'used_for_exact_price_matrix',true),'Owner-confirmed in project brief') ON DUPLICATE KEY UPDATE rule_json=VALUES(rule_json),source=VALUES(source)");
db()->exec("INSERT INTO product_process_guidance(process_code,owner_note,common_use,approved_product_specific,source) VALUES ('UV_PRINT','Used across many products; confirm each product and surface against an approved production profile.',1,0,'Owner-provided process guidance'),('UV_DTF','Used across many products; confirm each product and surface against an approved production profile.',1,0,'Owner-provided process guidance') ON DUPLICATE KEY UPDATE owner_note=VALUES(owner_note),common_use=VALUES(common_use),approved_product_specific=0,source=VALUES(source)");
echo 'Seeded catalogue and owner-confirmed rules. All product records remain drafts. Exact price matrix is intentionally empty.'.PHP_EOL;
